import time
import hashlib
import hmac
import os
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse
from threading import Lock
import secrets
import html

# Security configuration
SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32))
MAX_TOKENS = 10
REFILL_RATE = 1  # tokens per second
REFILL_INTERVAL = 1.0
MAX_REQUEST_SIZE = 4096
SESSION_DURATION = 3600

class TokenBucket:
    """Rate limiter using token bucket algorithm.

    Each client gets MAX_TOKENS tokens. Tokens are consumed per request.
    Tokens refill at REFILL_RATE per REFILL_INTERVAL seconds.
    When tokens reach 0, requests are denied until refill.
    """

    def __init__(self):
        self._buckets = {}
        self._lock = Lock()

    def _get_bucket(self, client_id):
        """Get or create a bucket for the client."""
        if client_id not in self._buckets:
            self._buckets[client_id] = {
                'tokens': MAX_TOKENS,
                'last_refill': time.monotonic()
            }
        return self._buckets[client_id]

    def _refill(self, bucket):
        """Refill tokens based on elapsed time."""
        now = time.monotonic()
        elapsed = now - bucket['last_refill']

        # Calculate tokens to add
        new_tokens = int(elapsed / REFILL_INTERVAL) * REFILL_RATE

        if new_tokens > 0:
            bucket['tokens'] = min(MAX_TOKENS, bucket['tokens'] + new_tokens)
            bucket['last_refill'] = now

    def consume(self, client_id, cost=1):
        """Attempt to consume tokens. Returns True if allowed."""
        with self._lock:
            bucket = self._get_bucket(client_id)
            self._refill(bucket)

            # Check if we have enough tokens before consuming
            if bucket['tokens'] >= cost:
                bucket['tokens'] -= cost
                return True
            else:
                # Not enough tokens - request denied
                return False


class SessionStore:
    """Secure in-memory session store."""

    def __init__(self):
        self._sessions = {}
        self._lock = Lock()

    def create_session(self, user_id):
        """Create a new session with a cryptographically random ID."""
        session_id = secrets.token_urlsafe(32)
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'created_at': time.time(),
                'expires_at': time.time() + SESSION_DURATION
            }
        return session_id

    def get_session(self, session_id):
        """Retrieve a session, checking expiration."""
        with self._lock:
            session = self._sessions.get(session_id)
            if session and session['expires_at'] > time.time():
                return session
            elif session:
                del self._sessions[session_id]
            return None

    def destroy_session(self, session_id):
        """Destroy a session."""
        with self._lock:
            self._sessions.pop(session_id, None)


# Global instances
rate_limiter = TokenBucket()
session_store = SessionStore()

# Simulated user database (passwords stored with HMAC)
USERS_DB = {}

def hash_password(password):
    """Hash password using HMAC-SHA256 with a per-user salt."""
    salt = secrets.token_bytes(16)
    h = hmac.new(salt, password.encode('utf-8'), hashlib.sha256).digest()
    return salt + h

def verify_password(stored, password):
    """Verify password against stored hash using constant-time comparison."""
    salt = stored[:16]
    expected = stored[16:]
    h = hmac.new(salt, password.encode('utf-8'), hashlib.sha256).digest()
    return hmac.compare_digest(h, expected)

def generate_csrf_token(session_id):
    """Generate a CSRF token bound to the session."""
    return hmac.new(
        SECRET_KEY.encode('utf-8'),
        session_id.encode('utf-8'),
        hashlib.sha256
    ).hexdigest()

def verify_csrf_token(session_id, token):
    """Verify CSRF token using constant-time comparison."""
    expected = generate_csrf_token(session_id)
    return hmac.compare_digest(expected, token)


class SecureHandler(BaseHTTPRequestHandler):
    """HTTP request handler with security controls."""

    def _get_client_id(self):
        """Extract client identifier for rate limiting."""
        # Use only the direct connection address - X-Forwarded-For
        # is not trusted without a known proxy configuration
        return self.client_address[0]

    def _check_rate_limit(self):
        """Check if request is within rate limits."""
        client_id = self._get_client_id()
        return rate_limiter.consume(client_id)

    def _get_session(self):
        """Extract and validate session from cookie."""
        cookie_header = self.headers.get('Cookie', '')
        for cookie in cookie_header.split(';'):
            cookie = cookie.strip()
            if cookie.startswith('session_id='):
                session_id = cookie[len('session_id='):]
                # Validate session ID format
                if len(session_id) > 64:
                    return None, None
                return session_id, session_store.get_session(session_id)
        return None, None

    def _read_body(self):
        """Safely read request body with size limit."""
        # Robustly parse Content-Length; reject malformed/negative values
        raw_len = self.headers.get('Content-Length', '0')
        try:
            content_length = int(raw_len)
        except (TypeError, ValueError):
            return None
        if content_length < 0:
            return None
        if content_length > MAX_REQUEST_SIZE:
            return None
        if content_length == 0:
            return b''
        return self.rfile.read(content_length)

    def _send_json(self, status, data):
        """Send a JSON response."""
        body = json.dumps(data).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('X-Frame-Options', 'DENY')
        self.send_header('Cache-Control', 'no-store')
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        """Handle GET requests."""
        if not self._check_rate_limit():
            self._send_json(429, {'error': 'Rate limit exceeded'})
            return

        parsed = urlparse(self.path)

        if parsed.path == '/api/profile':
            self._handle_profile()
        elif parsed.path == '/api/health':
            self._send_json(200, {'status': 'ok'})
        else:
            self._send_json(404, {'error': 'Not found'})

    def do_POST(self):
        """Handle POST requests."""
        if not self._check_rate_limit():
            self._send_json(429, {'error': 'Rate limit exceeded'})
            return

        parsed = urlparse(self.path)

        if parsed.path == '/api/login':
            self._handle_login()
        elif parsed.path == '/api/data':
            self._handle_data()
        else:
            self._send_json(404, {'error': 'Not found'})

    def _handle_login(self):
        """Handle login - authenticate and create session."""
        body = self._read_body()
        if body is None:
            self._send_json(413, {'error': 'Request too large'})
            return

        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self._send_json(400, {'error': 'Invalid JSON'})
            return

        username = data.get('username', '')
        password = data.get('password', '')

        # Input validation
        if not isinstance(username, str) or not isinstance(password, str):
            self._send_json(400, {'error': 'Invalid input types'})
            return

        if len(username) > 64 or len(password) > 128:
            self._send_json(400, {'error': 'Input too long'})
            return

        # Check credentials
        user = USERS_DB.get(username)
        if user and verify_password(user['password_hash'], password):
            session_id = session_store.create_session(username)
            csrf_token = generate_csrf_token(session_id)

            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Cache-Control', 'no-store')
            self.send_header('Set-Cookie', 
                f'session_id={session_id}; HttpOnly; Secure; SameSite=Strict; Path=/')
            resp = json.dumps({'csrf_token': csrf_token}).encode('utf-8')
            self.send_header('Content-Length', str(len(resp)))
            self.end_headers()
            self.wfile.write(resp)
        else:
            # Constant-time response to prevent user enumeration
            time.sleep(0.1)
            self._send_json(401, {'error': 'Invalid credentials'})

    def _handle_profile(self):
        """Handle profile retrieval - requires authentication."""
        session_id, session = self._get_session()
        if not session:
            self._send_json(401, {'error': 'Authentication required'})
            return

        self._send_json(200, {
            'user_id': session['user_id'],
            'session_created': session['created_at']
        })

    def _handle_data(self):
        """Handle data submission - requires auth + CSRF."""
        session_id, session = self._get_session()
        if not session:
            self._send_json(401, {'error': 'Authentication required'})
            return

        # Verify CSRF token
        csrf_token = self.headers.get('X-CSRF-Token', '')
        if not verify_csrf_token(session_id, csrf_token):
            self._send_json(403, {'error': 'Invalid CSRF token'})
            return

        body = self._read_body()
        if body is None:
            self._send_json(413, {'error': 'Request too large'})
            return

        try:
            data = json.loads(body)
        except (json.JSONDecodeError, ValueError):
            self._send_json(400, {'error': 'Invalid JSON'})
            return

        # Sanitize and validate data
        if not isinstance(data, dict):
            self._send_json(400, {'error': 'Expected object'})
            return

        sanitized = {}
        for key, value in data.items():
            if isinstance(key, str) and len(key) <= 64:
                safe_key = html.escape(key)
                if isinstance(value, (str, int, float, bool)):
                    sanitized[safe_key] = value

        self._send_json(200, {'stored': len(sanitized), 'status': 'ok'})


